/* Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT */
:where([data-moru-registry]) .ui-menubar {
  box-sizing: border-box;
  min-width: 0;
  font-family: var(--ui-font-family, inherit);
  font-size: var(--ui-type-label-size, 13px);
  font-weight: var(--ui-type-label-weight, 550);
  line-height: var(--ui-type-label-line-height, 1.5);
  letter-spacing: var(--ui-type-label-letter-spacing, -0.015em);
  color: var(--ui-text, #171717);
  overflow-wrap: anywhere;
  --ui-navigation-height: var(--ui-control-height-md, 40px);
  --ui-navigation-padding: var(--ui-control-padding-x-md, 14px);
  --ui-navigation-icon: var(--ui-icon-size-md, 16px);
  --ui-navigation-close-size: var(--ui-control-height-sm, 32px);
}
:where([data-moru-registry]) [data-size='sm'].ui-menubar {
  --ui-navigation-height: var(--ui-control-height-sm, 32px);
  --ui-navigation-padding: var(--ui-control-padding-x-sm, 10px);
  --ui-navigation-icon: var(--ui-icon-size-sm, 14px);
  font-size: var(--ui-type-caption-size, 12px);
}
:where([data-moru-registry]) [data-size='lg'].ui-menubar {
  --ui-navigation-height: var(--ui-control-height-lg, 48px);
  --ui-navigation-padding: var(--ui-control-padding-x-lg, 18px);
  --ui-navigation-icon: var(--ui-icon-size-lg, 18px);
}
:where([data-moru-registry]) .ui-menubar {
  display: inline-flex;
  max-width: 100%;
  flex-wrap: wrap;
  padding: calc(var(--ui-space, 4px) * 0.75);
  gap: calc(var(--ui-space, 4px) / 2);
  border: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
  border-radius: var(--ui-radius, 6px);
  background: var(--ui-control-hover-bg, #f3f3f1);
}
:where([data-moru-registry]) .ui-menubar-trigger {
  display: inline-flex;
  box-sizing: border-box;
  min-width: 0;
  max-width: 100%;
  align-items: center;
  justify-content: center;
  gap: var(--ui-field-gap, 8px);
  min-height: var(--ui-navigation-height);
  padding: var(--ui-space, 4px) var(--ui-navigation-padding);
  border: 0;
  border-radius: max(3px, calc(var(--ui-radius, 6px) - 4px));
  background: transparent;
  color: inherit;
  font: inherit;
  text-decoration: none;
  cursor: pointer;
}
:where([data-moru-registry]) .ui-menubar-trigger[data-popup-open] {
  background: var(--ui-primary, #181818);
  color: var(--ui-primary-foreground, #fff);
}
:where([data-moru-registry]) .ui-menubar-trigger:hover:not([data-disabled]) {
  background: var(--ui-control-hover-bg, #f3f3f1);
}
:where([data-moru-registry]) .ui-menubar-trigger[data-popup-open]:hover:not([data-disabled]) {
  background: var(--ui-primary-hover, #303030);
  color: var(--ui-primary-hover-foreground, #fff);
}
:where([data-moru-registry]) .ui-menubar-trigger[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
:where([data-moru-registry]) .ui-menubar:focus-visible {
  outline: 2px solid var(--ui-focus-ring, #181818);
  outline-offset: 2px;
}

@media (pointer: coarse) {
  :where([data-moru-registry]) .ui-menubar-trigger {
    min-height: max(44px, var(--ui-navigation-height, 40px));
  }
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { useI18n } from './_lib/i18n'
import { useEffect, useRef, useState } from 'react'
import { Menubar as BaseMenubar } from '@base-ui/react/menubar'
import { Menu as BaseMenu } from '@base-ui/react/menu'
import { cn } from './_lib/cn'
import { NavigationMenuActions, type NavigationAction } from './navigation-menu-items'
import { useThemePortalContainer } from './theme-scope'
import { OverlayPortal } from './overlay-portal'
import './navigation-shared.css'
import './menubar.css'

export interface MenubarMenu {
  id: string
  label: string
  disabled?: boolean
  items: NavigationAction[]
}
export interface MenubarProps {
  menus: MenubarMenu[]
  disabled?: boolean
  size?: 'sm' | 'md' | 'lg'
  className?: string
  'aria-label'?: string
}
export function Menubar({
  menus,
  disabled,
  size = 'md',
  className,
  'aria-label': labelProp,
}: MenubarProps) {
  const { t } = useI18n()
  const label = labelProp ?? t('애플리케이션 메뉴')

  const portalContainer = useThemePortalContainer()
  const rootRef = useRef<HTMLDivElement>(null)
  const popupRefs = useRef(new Map<string, HTMLDivElement>())
  const [openId, setOpenId] = useState<string | null>(null)
  const available = !disabled && menus.some((menu) => menu.id === openId && !menu.disabled)
  useEffect(() => {
    if (openId !== null && !available) setOpenId(null)
  }, [openId, available])
  return (
    <BaseMenubar
      ref={rootRef}
      tabIndex={-1}
      className={cn('ui-menubar', className)}
      aria-label={label}
      disabled={disabled}
      data-disabled={disabled || undefined}
      data-size={size}
    >
      {menus.map((menu) => (
        <BaseMenu.Root
          key={menu.id}
          disabled={disabled || menu.disabled}
          open={available && openId === menu.id}
          onOpenChange={(next) => {
            if (next && (disabled || menu.disabled)) return
            setOpenId((current) => (next ? menu.id : current === menu.id ? null : current))
          }}
        >
          <BaseMenu.Trigger className="ui-menubar-trigger">{menu.label}</BaseMenu.Trigger>
          <OverlayPortal portal={BaseMenu.Portal} kind="menu" container={portalContainer}>
            <BaseMenu.Positioner
              className="ui-navigation-positioner"
              positionMethod="fixed"
              align="start"
              sideOffset={6}
              collisionPadding={12}
            >
              <BaseMenu.Popup
                ref={(node) => {
                  if (node) popupRefs.current.set(menu.id, node)
                  else popupRefs.current.delete(menu.id)
                }}
                className="ui-navigation-popup"
                data-size={size}
                finalFocus={
                  disabled || menu.disabled
                    ? () => {
                        const root = rootRef.current
                        if (!root) return false
                        const active = root.ownerDocument.activeElement
                        if (
                          active !== root.ownerDocument.body &&
                          !popupRefs.current.get(menu.id)?.contains(active)
                        )
                          return false
                        const triggers = Array.from(
                          root.querySelectorAll<HTMLButtonElement>('.ui-menubar-trigger'),
                        )
                        const index = menus.findIndex((candidate) => candidate.id === menu.id)
                        return (
                          [...triggers.slice(index + 1), ...triggers.slice(0, index)].find(
                            (trigger) => !trigger.disabled,
                          ) ?? root
                        )
                      }
                    : undefined
                }
              >
                <NavigationMenuActions items={menu.items} size={size} />
              </BaseMenu.Popup>
            </BaseMenu.Positioner>
          </OverlayPortal>
        </BaseMenu.Root>
      ))}
    </BaseMenubar>
  )
}
